// Starter file for MongoDB Aggregation Framework and Mongoose
// Task instructions:
// Build an analytics dashboard using MongoDB aggregation. Create pipelines for: top customers, revenue by month, category performance, and product ratin...

solution_code:
// Aggregation: top-selling products
const topProducts = await orders.aggregate([
  { $match: { status: { $in: ["paid", "shipped", "delivered"] } } },
  { $unwind: "$items" },
  { $group: {
      _id: "$items.productId",
      totalSold: { $sum: "$items.quantity" },
      totalRevenue: { $sum: { $multiply: ["$items.quantity", "$items.price"] } }
  }},
  { $lookup: {
      from: "products",
      localField: "_id",
      foreignField: "_id",
      as: "product"
  }},
  { $unwind: "$product" },
  { $project: {
      _id: 0,
      name: "$product.name",
      totalSold: 1,
      totalRevenue: 1,
      averagePrice: { $divide: ["$totalRevenue", "$totalSold"] }
  }},
  { $sort: { totalRevenue: -1 } },
  { $limit: 10 }
]).toArray();

// Faceted search: multiple aggregations in one query
const facetedResults = await products.aggregate([
  { $match: { category: "electronics" } },
  { $facet: {
      byPrice: [
        { $bucket: {
            groupBy: "$price",
            boundaries: [0, 50, 100, 500, 1000],
            default: "1000+",
            output: { count: { $sum: 1 } }
        }}
      ],
      byBrand: [
        { $group: { _id: "$brand", count: { $sum: 1 } } },
        { $sort: { count: -1 } }
      ],
      stats: [
        { $group: {
            _id: null,
            avgPrice: { $avg: "$price" },
            minPrice: { $min: "$price" },
            maxPrice: { $max: "$price" },
            total: { $sum: 1 }
        }}
      ]
  }}
]).toArray();
